import (
	"fmt"
	"reasonix/internal/agent"
	"reasonix/internal/event"
	"reasonix/internal/provider"
	"strings"
)

func historyLocalOnlyRows(m provider.Message) ([]HistoryMessage, bool) {
	if !m.LocalOnly {
		return nil, false
	}
	if m.ReadPause != nil {
		return []HistoryMessage{{Role: "notice", Code: event.TurnOutcomeIncompleteRead, Level: "info", ReadPause: m.ReadPause}}, true
	}
	if m.ReadCompletion != nil {
		return []HistoryMessage{{Role: "notice", Code: "read_completion", Level: "info", Content: "Partial read coverage was accepted for this turn.", Detail: formatReadCompletionDetail(m.ReadCompletion), ReadCompletion: m.ReadCompletion}}, true
	}
	if len(m.ProtocolRecovery) > 0 {
		if r, ok := provider.DecodeProtocolRecovery(m.ProtocolRecovery); ok && r.State == "pending" {
			return []HistoryMessage{{Role: "notice", Code: "protocol_recovery", Level: "info", Pending: true, ProtocolRecovery: &provider.ProtocolRecoveryAction{ID: r.ID}}}, true
		}
		return nil, true
	}
	if readiness := agent.HistoricalChecks(m.FinalReadinessRecovery); readiness != nil {
		return []HistoryMessage{{Role: "notice", Code: agent.HistoricalChecksNoticeCode, Level: "info",
			Content: agent.HistoricalChecksNoticeText, Readiness: readiness}}, true
	}
	return historySteerRows(m.Content, true)
}

func formatReadCompletionDetail(r *provider.ReadCompletion) string {
	if r == nil {
		return ""
	}
	parts := make([]string, 0, len(r.Reads))
	for _, read := range r.Reads {
		parts = append(parts, fmt.Sprintf("%s · %s · covered=%v", read.Path, read.Verdict, read.Covered))
	}
	return strings.Join(parts, "\n")
}

import BasicObject from "trix/core/basic_object"

export default class UndoManager extends BasicObject {
  constructor(composition) {
    super(...arguments)
    this.composition = composition
    this.undoEntries = []
    this.redoEntries = []
  }

  recordUndoEntry(description, { context, consolidatable } = {}) {
    const previousEntry = this.undoEntries.slice(-1)[0]

    if (!consolidatable || !entryHasDescriptionAndContext(previousEntry, description, context)) {
      const undoEntry = this.createEntry({ description, context })
      this.undoEntries.push(undoEntry)
      this.redoEntries = []
    }
  }

  undo() {
    const undoEntry = this.undoEntries.pop()
    if (undoEntry) {
      const redoEntry = this.createEntry(undoEntry)
      this.redoEntries.push(redoEntry)
      return this.composition.loadSnapshot(undoEntry.snapshot)
    }
  }

  redo() {
    const redoEntry = this.redoEntries.pop()
    if (redoEntry) {
      const undoEntry = this.createEntry(redoEntry)
      this.undoEntries.push(undoEntry)
      return this.composition.loadSnapshot(redoEntry.snapshot)
    }
  }

  canUndo() {
    return this.undoEntries.length > 0
  }

  canRedo() {
    return this.redoEntries.length > 0
  }

  // Private

  createEntry({ description, context } = {}) {
    return {
      description: description?.toString(),
      context: JSON.stringify(context),
      snapshot: this.composition.getSnapshot(),
    }
  }
}

const entryHasDescriptionAndContext = (entry, description, context) =>
  entry?.description === description?.toString() && entry?.context === JSON.stringify(context)

import {
  assert,
  clickToolbarButton,
  expandSelection,
  moveCursor,
  test,
  testGroup,
  typeCharacters,
} from "test/test_helper"

testGroup("Undo/Redo", { template: "editor_empty" }, async () => {
  test("typing and undoing", async () => {
    const first = getDocument().copy()
    await typeCharacters("abc")
    assert.notOk(getDocument().isEqualTo(first))
    await clickToolbarButton({ action: "undo" })
    assert.ok(getDocument().isEqualTo(first))
  })

  test("typing, formatting, typing, and undoing", async () => {
    const first = getDocument().copy()
    await typeCharacters("abc")
    const second = getDocument().copy()
    await clickToolbarButton({ attribute: "bold" })
    await typeCharacters("def")
    const third = getDocument().copy()
    await clickToolbarButton({ action: "undo" })
    assert.ok(getDocument().isEqualTo(second))
    await clickToolbarButton({ action: "undo" })
    assert.ok(getDocument().isEqualTo(first))
    await clickToolbarButton({ action: "redo" })
    assert.ok(getDocument().isEqualTo(second))
    await clickToolbarButton({ action: "redo" })
    assert.ok(getDocument().isEqualTo(third))
  })

  test("formatting changes are batched by location range", async () => {
    await typeCharacters("abc")
    const first = getDocument().copy()
    await expandSelection("left")
    await clickToolbarButton({ attribute: "bold" })
    await clickToolbarButton({ attribute: "italic" })
    const second = getDocument().copy()
    await moveCursor("left")
    await expandSelection("left")
    await clickToolbarButton({ attribute: "italic" })
    const third = getDocument().copy()
    await clickToolbarButton({ action: "undo" })
    assert.ok(getDocument().isEqualTo(second))
    await clickToolbarButton({ action: "undo" })
    assert.ok(getDocument().isEqualTo(first))
    await clickToolbarButton({ action: "redo" })
    assert.ok(getDocument().isEqualTo(second))
    await clickToolbarButton({ action: "redo" })
    assert.ok(getDocument().isEqualTo(third))
  })

  test("block formatting are undoable", async () => {
    await typeCharacters("abc")
    const first = getDocument().copy()
    await clickToolbarButton({ attribute: "heading1" })
    const second = getDocument().copy()
    await clickToolbarButton({ action: "undo" })
    assert.ok(getDocument().isEqualTo(first))
    clickToolbarButton({ action: "redo" })
    assert.ok(getDocument().isEqualTo(second))
  })
})

import { Operation } from 'slate';

import type { YooptaOperation } from './applyTransforms';
import { Blocks } from '../blocks';
import type { SlateElement, YooEditor, YooptaPath } from '../types';

export type HistoryStack = {
  operations: YooptaOperation[];
  path: YooptaPath;
};

export type HistoryStackName = 'undos' | 'redos';

export function inverseEditorOperation(
  editor: YooEditor,
  op: YooptaOperation,
): YooptaOperation | YooptaOperation[] {
  switch (op.type) {
    case 'insert_block':
      return {
        type: 'delete_block',
        path: op.path,
        block: op.block,
      };

    case 'delete_block':
      return {
        type: 'insert_block',
        path: op.path,
        block: op.block,
      };

    case 'set_block_meta': {
      return {
        type: 'set_block_meta',
        id: op.id,
        properties: op.prevProperties,
        prevProperties: op.properties,
      };
    }

    case 'split_block': {
      return [
        {
          type: 'delete_block',
          block: op.properties.nextBlock,
          path: op.path,
        },
        {
          type: 'set_block_value',
          id: op.prevProperties.originalBlock.id,
          value: op.prevProperties.originalValue as SlateElement[],
          forceSlate: true,
        },
      ];
    }

    case 'toggle_block': {
      return {
        type: 'toggle_block',
        properties: {
          toggledBlock: op.prevProperties.sourceBlock,
          toggledSlateValue: op.prevProperties.sourceSlateValue,
        },
        prevProperties: {
          sourceBlock: op.properties.toggledBlock,
          sourceSlateValue: op.properties.toggledSlateValue,
        },
      };
    }

    case 'merge_block': {
      return [
        {
          type: 'split_block',
          properties: {
            nextBlock: op.prevProperties.sourceBlock,
            nextSlateValue: op.prevProperties.sourceSlateValue,
            splitSlateValue: op.prevProperties.targetSlateValue,
          },
          prevProperties: {
            originalBlock: op.properties.mergedBlock,
            originalValue: op.properties.mergedSlateValue,
          },
          path: op.path,
        },
      ];
    }

    case 'move_block': {
      return {
        type: 'move_block',
        properties: op.prevProperties,
        prevProperties: op.properties,
      };
    }

    case 'set_slate': {
      const inverseOps = op.properties.slateOps.map(Operation.inverse).reverse();
      return {
        type: 'set_slate',
        properties: {
          slateOps: inverseOps,
          selectionBefore: op.properties.selectionBefore,
        },
        slate: op.slate,
        blockId: op.blockId,
      };
    }

    case 'set_editor_value': {
      return {
        type: 'set_editor_value',
        properties: op.prevProperties,
        prevProperties: op.properties,
      };
    }

    default:
      return op;
  }
}

export type UndoRedoOptions = {
  scroll?: boolean;
};

export const SAVING = new WeakMap<YooEditor, boolean | undefined>();
export const MERGING = new WeakMap<YooEditor, boolean | undefined>();

export const YooptaHistory = {
  isMergingHistory(editor: YooEditor): boolean | undefined {
    return MERGING.get(editor);
  },

  isSavingHistory(editor: YooEditor): boolean | undefined {
    return SAVING.get(editor);
  },

  withMergingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isMergingHistory(editor);
    MERGING.set(editor, true);
    fn();
    MERGING.set(editor, prev);
  },

  withSavingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isSavingHistory(editor);
    SAVING.set(editor, true);
    fn();
    SAVING.set(editor, prev);
  },

  withoutMergingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isMergingHistory(editor);
    MERGING.set(editor, false);
    fn();
    MERGING.set(editor, prev);
  },

  withoutSavingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isSavingHistory(editor);
    SAVING.set(editor, false);
    fn();
    SAVING.set(editor, prev);
  },

  redo: (editor: YooEditor, options?: UndoRedoOptions) => {
    const { redos } = editor.historyStack;

    if (redos.length > 0) {
      const batch = redos[redos.length - 1];

      YooptaHistory.withoutSavingHistory(editor, () => {
        editor.applyTransforms(batch.operations, { source: 'history' });
        editor.setPath(batch.path);

        const { scroll = true } = options || {};
        if (scroll && typeof batch.path.current === 'number') {
          const block = Blocks.getBlock(editor, { at: batch.path.current });

          // [TODO] - not good place to scroll. View tasks should be separated from model tasks
          const blockElement = document.querySelector(`[data-yoopta-block-id="${block?.id}"]`);
          if (blockElement && !isInViewport(blockElement)) {
            blockElement.scrollIntoView({ block: 'center', behavior: 'auto' });
          }
        }
      });

      editor.historyStack.redos.pop();
      editor.historyStack.undos.push(batch);
    }
  },
  undo: (editor: YooEditor, options?: UndoRedoOptions) => {
    const { undos } = editor.historyStack;

    if (undos.length > 0) {
      const batch = editor.historyStack.undos[editor.historyStack.undos.length - 1];

      YooptaHistory.withoutSavingHistory(editor, () => {
        // [TODO] - ask Christopher Nolan to help with this
        const inverseOps = batch.operations
          .flatMap((op) => inverseEditorOperation(editor, op))
          .reverse();
        editor.applyTransforms(inverseOps, { source: 'history' });
        editor.setPath(batch.path);

        const { scroll = true } = options || {};
        if (scroll && typeof batch.path.current === 'number') {
          const block = Blocks.getBlock(editor, { at: batch.path.current });

          // [TODO] - not good place to scroll. View tasks should be separated from model tasks
          const blockElement = document.querySelector(`[data-yoopta-block-id="${block?.id}"]`);
          if (blockElement && !isInViewport(blockElement)) {
            blockElement.scrollIntoView({ block: 'center', behavior: 'auto' });
          }
        }
      });

      editor.historyStack.redos.push(batch);
      editor.historyStack.undos.pop();
    }
  },
};

function isInViewport(element) {
  const rect = element.getBoundingClientRect();
  const html = document.documentElement;
  return (
    rect.top >= 0 &&
    rect.left >= 0 &&
    rect.bottom <= (window.innerHeight || html.clientHeight) &&
    rect.right <= (window.innerWidth || html.clientWidth)
  );
}

import cloneDeep from 'clone-deep'
import { checkLastSaved, _toggleCanUndo, _toggleCanRedo } from '@/store/types'

const MAX_HISTORY = 250

/**
 * Vue Mixin to control the State history and undo/redo functionality
 *
 * @type {Vue.mixin}
 * @see {@link https://vuejs.org/v2/guide/mixins.html|Vue Mixins}
 */
const redoundo = {
  data: function () {
    return {
      done: [],
      undone: []
    }
  },

  created: function () {
    this.$store.subscribe((mutation, state) => {
      // If the history size is reached, the eldest state will be removed
      if (this.done.length === MAX_HISTORY) this.done.shift()

      // It won't save the state of mutations leaded by '_'
      if (mutation.type.charAt(0) !== '_') {
        this.done.push(cloneDeep(state))
        this.undone = []

        // To display if changes had happened to the project
        this.updateCanRedoUndo()
        this.$store.dispatch(checkLastSaved)
      }
    })

    this.$root.$on('undo', this.undo)
    this.$root.$on('redo', this.redo)
  },

  beforeDestroy: function () {
    this.$root.$off('undo', this.undo)
    this.$root.$off('redo', this.redo)
  },

  computed: {
    canUndo () {
    // There should always be at least one state (initializeState)
      return this.done.length > 1
    },
    canRedo () {
      return this.undone.length > 0
    }
  },

  methods: {
    undo () {
      if (this.canUndo) {
        this.undone.push(this.done.pop())
        let undoState = this.done[this.done.length - 1]
        this.$store.replaceState(cloneDeep(undoState))
        this.$root.$emit('rebaseState')
        this.updateCanRedoUndo()
      }
    },

    redo () {
      if (this.canRedo) {
        let redoState = this.undone.pop()
        this.done.push(redoState)
        this.$store.replaceState(cloneDeep(redoState))
        this.$root.$emit('rebaseState')
        this.updateCanRedoUndo()
      }
    },

    updateCanRedoUndo () {
      this.$store.commit(_toggleCanUndo, this.canUndo)
      this.$store.commit(_toggleCanRedo, this.canRedo)
    }
  }
}

export default redoundo
